   727  int r_bin_omf_get_bits(r_bin_omf_obj *obj) {
   728          ut32 ct_sec = 0;
   729          if (!obj) {
   730                  return 32;
   731          }
   732
   733          // we assume if one segdef define a 32 segment all opcodes are 32bits
   734          while (ct_sec < obj->nb_section) {
   735                  if (obj->sections[ct_sec++]->bits == 32) {
   736                          return 32;
   737                  }
   738          }
   739          return 16;
   740  }
